// Cristal completo (incluye la chispa encendida).
part("cristal", () => {
  base();
});

// Chispa pequeña de la esquina superior izquierda. nivel: 0 apagada, 1 pequeña, 2 completa (la de la base).
part("chispa", ({ nivel = 2 } = {}) => {
  if (nivel === 2) return;
  // Borra la chispa y deja solo el resplandor tenue de fondo.
  fill_rect(7, 7, 5, 5, "transparent");
  fill_rect(7, 7, 5, 5, "#3f32073f");
  if (nivel === 1) {
    set_pixel(9, 8, "#b3943bb3");
    set_pixel(8, 9, "#b3943bb3");
    set_pixel(9, 9, "#f8ebc8f8");
    set_pixel(10, 9, "#b3943bb3");
    set_pixel(9, 10, "#b3943bb3");
  }
});

// Interior dorado del cristal por filas: [y, x_ini, x_fin].
const INTERIOR = [
  [5, 15, 16], [6, 15, 16], [7, 14, 17], [8, 14, 17], [9, 14, 17],
  [10, 13, 18], [11, 13, 18], [12, 12, 19], [13, 10, 21], [14, 7, 24],
  [15, 5, 26], [16, 5, 26], [17, 7, 23], [18, 10, 20], [19, 12, 18],
  [20, 13, 18], [21, 13, 17], [22, 14, 17], [23, 14, 16], [24, 15, 16],
  [25, 15, 16], [26, 15, 16],
];

// Destello diagonal: aclara las caras en la franja x + y ≈ pos.
part("destello", ({ pos }) => {
  for (const [y, x0, x1] of INTERIOR) {
    for (let x = x0; x <= x1; x++) {
      const d = x + y - pos;
      if (d < -1 || d > 2) continue;
      const centro = d === 0 || d === 1;
      if (y <= 15) set_pixel(x, y, centro ? "#fffbe0" : "#fff2ac");
      else set_pixel(x, y, centro ? "#ffe866" : "#ffd21a");
    }
  }
});

// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
rest(() => {
  draw("cristal");
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
action("brillo", { frames: 6, fps: 10, loop: true }, (f, { t }) => {
  const dy = cycle([0, 0, -1, -1, -1, 0], f);
  const pos = cycle([18, 24, 30, 36, 42, null], f);
  move(0, dy, () => {
    draw("cristal");
    if (pos !== null) draw("destello", { pos });
    draw("chispa", { nivel: cycle([0, 1, 2, 2, 1, 0], f) });
  });
});

